import { createRequire } from 'node:module';
const require = createRequire(process.argv[2] + '/package.json');
const { chromium } = require('playwright-core');
const exe = process.argv[3];
const URL = 'http://127.0.0.1:41077/';
const shots = process.argv[4];
const out = [];
const log = (...a) => { out.push(a.join(' ')); console.log(...a); };

const browser = await chromium.launch({ executablePath: exe });
for (const scheme of ['dark', 'light']) {
  for (const [w, h] of [[360, 780], [1280, 860]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, colorScheme: scheme });
    const page = await ctx.newPage();
    const errors = [];
    page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
    page.on('pageerror', (e) => errors.push(String(e)));
    await page.goto(URL, { waitUntil: 'networkidle' });
    const tag = `${scheme}@${w}`;
    const info = await page.evaluate(() => {
      const cs = getComputedStyle(document.documentElement);
      const list = document.querySelector('[aria-label="Pantry items"]').getBoundingClientRect();
      const detail = document.querySelectorAll('section')[1].getBoundingClientRect();
      const btn = getComputedStyle(document.querySelector('button[type="submit"]'));
      return {
        accent: cs.getPropertyValue('--ult-color-accent').trim(),
        surface: cs.getPropertyValue('--ult-color-surface').trim(),
        scheme: cs.colorScheme,
        bodyBg: getComputedStyle(document.body).backgroundColor,
        rootBg: cs.backgroundColor,
        submitBg: btn.backgroundColor,
        font: cs.fontFamily.slice(0, 30),
        sideways: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        scrollW: document.documentElement.scrollWidth,
        sideBySide: Math.abs(list.top - detail.top) < 200 && detail.left > list.right - 1,
      };
    });
    log(tag, JSON.stringify(info));
    await page.screenshot({ path: `${shots}/${tag}.png`, fullPage: true });

    if (w === 1280 || scheme === 'dark') {
      // Select a different item.
      await page.getByRole('button', { name: 'Apples' }).click();
      log(tag, 'detail after select:', await page.locator('section').nth(1).locator('h2').textContent(), 'pressed:', await page.getByRole('button', { name: 'Apples' }).getAttribute('aria-pressed'));
      // Submit empty.
      await page.getByRole('button', { name: 'Log donation' }).click();
      const name = page.getByLabel('Item name');
      log(tag, 'empty submit: aria-invalid', await name.getAttribute('aria-invalid'), 'error:', await page.getByText('Enter an item name.').isVisible(), 'focused name:', await name.evaluate((el) => el === document.activeElement), 'describedby->', await name.evaluate((el) => (el.getAttribute('aria-describedby') || '').split(' ').map((id) => document.getElementById(id)?.textContent).join('|')));
      const err = await page.getByText('Enter an item name.').boundingBox();
      const inp = await name.boundingBox();
      log(tag, 'error directly below input:', err.y >= inp.y + inp.height - 1 && err.y - (inp.y + inp.height) < 30);
      // Category select by keyboard.
      const trigger = page.getByRole('combobox', { name: 'Category' });
      await trigger.focus();
      await page.keyboard.press('Enter');
      const popup = page.getByRole('listbox');
      await popup.waitFor();
      const portal = await popup.evaluate((el) => {
        let n = el; while (n.parentElement && n.parentElement !== document.body) n = n.parentElement;
        const form = document.querySelector('form');
        return { underBody: n.parentElement === document.body, insideForm: form.contains(el), bg: getComputedStyle(el.closest('[role=listbox]') ? el : el).backgroundColor, accentVar: getComputedStyle(el).getPropertyValue('--ult-color-accent').trim(), scheme: getComputedStyle(el).colorScheme };
      });
      log(tag, 'select open via Enter, portal:', JSON.stringify(portal));
      if (w === 1280) await page.screenshot({ path: `${shots}/${tag}-select-open.png` });
      await page.keyboard.press('Escape');
      await popup.waitFor({ state: 'hidden' });
      log(tag, 'Escape closed; focus on trigger:', await trigger.evaluate((el) => el === document.activeElement));
      // Choose Produce with keyboard.
      await page.keyboard.press('ArrowDown');
      await popup.waitFor();
      for (let i = 0; i < 3; i++) {
        const hl = await page.locator('[role=option][data-highlighted]').textContent().catch(() => '');
        if (hl.includes('Produce')) break;
        await page.keyboard.press('ArrowDown');
      }
      await page.keyboard.press('Enter');
      await popup.waitFor({ state: 'hidden' });
      log(tag, 'chosen:', await trigger.textContent(), 'focus on trigger:', await trigger.evaluate((el) => el === document.activeElement));
      // Valid new item.
      await name.fill('Carrots');
      await page.getByLabel('Quantity').fill('15');
      await page.getByRole('button', { name: 'Log donation' }).click();
      log(tag, 'status:', await page.getByRole('status').textContent());
      log(tag, 'new row exists:', await page.getByRole('button', { name: 'Carrots' }).count(), 'detail:', await page.locator('section').nth(1).innerText().then((t) => t.replace(/\n+/g, ' / ')));
      // Existing item adds.
      await name.fill('black beans');
      await page.getByLabel('Quantity').fill('8');
      await page.getByRole('button', { name: 'Log donation' }).click();
      log(tag, 'status:', await page.getByRole('status').textContent());
      // Bad quantity.
      await name.fill('Rice');
      await page.getByLabel('Quantity').fill('0');
      await page.getByRole('button', { name: 'Log donation' }).click();
      log(tag, 'qty error:', await page.getByText('Enter a whole number of 1 or more.').isVisible());
      log(tag, 'sideways after edits:', await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth));
      // Keyboard on list.
      await page.getByRole('button', { name: 'Carrots' }).focus();
      await page.keyboard.press('ArrowUp');
      await page.keyboard.press('Enter');
      log(tag, 'keyboard select ->', await page.locator('section').nth(1).locator('h2').textContent());
    }
    log(tag, 'console errors:', JSON.stringify(errors));
    await ctx.close();
  }
}
// Explicit data-theme modes override the system preference.
const ctx = await browser.newContext({ colorScheme: 'dark' });
const page = await ctx.newPage();
await page.goto(URL, { waitUntil: 'networkidle' });
for (const mode of ['light', 'dark']) {
  await page.evaluate((m) => document.documentElement.setAttribute('data-theme', m), mode);
  log('data-theme', mode, await page.evaluate(() => { const c = getComputedStyle(document.documentElement); return c.getPropertyValue('--ult-color-accent').trim() + ' ' + c.colorScheme; }));
}
// Reduced motion.
await page.emulateMedia({ reducedMotion: 'reduce' });
log('reduced motion fast:', await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--ult-motion-fast').trim()));
await browser.close();
EOF
